"""Command. Share the existing paired controller between left and right owners."""
from pathlib import Path
with Path('agents/manifest.md').open('a') as f:f.write('\nRight puppet requested: reuse identical seven-axis controller per side, one paired SDK owner each; remove separate right telemetry ownership. Side selection routes UI/API; shared preset lock excludes concurrent modes. Existing left endpoint defaults preserved.\n')
p=Path('web/source/backend/puppet.py');s=p.read_text().replace('def __init__(self, stop, publish, presets=None):','def __init__(self, stop, publish, presets=None, side="left"):').replace('        self.stop, self.publish = stop, publish','        if side not in ("left", "right"):\n            raise ValueError("Unknown pair side")\n        self.side = side\n        self.leader, self.follower = f"leader_{side}", f"follower_{side}"\n        self.stop_order = (self.follower, self.leader)\n        self.stop, self.publish = stop, publish')
s=s.replace('for role in STOP_ORDER:', 'for role in self.stop_order:').replace('self.sdk("leader_left",','self.sdk(self.leader,').replace('self.sdk("follower_left",','self.sdk(self.follower,').replace('(("leader_left", leader_ref), ("follower_left", raw))','((self.leader, leader_ref), (self.follower, raw))').replace('("follower_left", "set_', '(self.follower, "set_').replace('("leader_left", "set_', '(self.leader, "set_').replace('{"leader_left": arm.Mode.external_effort, "follower_left": arm.Mode.position}','{self.leader: arm.Mode.external_effort, self.follower: arm.Mode.position}')
s=s.replace('for role, ip, preset in (("leader_left", "192.168.1.3", arm.StandardEndEffector.wxai_v0_leader),\n                                     ("follower_left", "192.168.1.5", arm.StandardEndEffector.wxai_v0_follower)):', 'for role, ip, preset in ((self.leader, "192.168.1.3" if self.side == "left" else "192.168.1.2", arm.StandardEndEffector.wxai_v0_leader),\n                                     (self.follower, "192.168.1.5" if self.side == "left" else "192.168.1.4", arm.StandardEndEffector.wxai_v0_follower)):')
s=s.replace('raise StartNotReady("Use Up on both left arms first: upright, wrists reset, grippers open")','raise StartNotReady(f"Use Up on both {self.side} arms first: upright, wrists reset, grippers open")').replace('raise StartNotReady("Align the left base headings before enabling puppet mode")','raise StartNotReady(f"Align the {self.side} base headings before enabling puppet mode")')
s=s.replace('            if action == "arm" and self.presets and self.presets.busy():','            if action == "arm" and self.presets:\n                for pair in self.presets.pairs.values():\n                    if pair is not self and (pair.enabled or pair.stop_pending or pair.state["active"] is not False):\n                        raise ValueError("Stop the other puppet pair first")\n            if action == "arm" and self.presets and self.presets.busy():')
s=s.replace('LOG.warning("Left puppet active: absolute seven-joint copying engaged from upright")','LOG.warning("%s puppet active: absolute seven-joint copying engaged from upright", self.side)')
p.write_text(s)
p=Path('web/source/backend/presets.py');s=p.read_text().replace('        self.pair = None','        self.pair = None\n        self.pairs = {}').replace('                pair = self.pair.snapshot()','                pair = self.pairs.get(role.rsplit("_", 1)[-1], self.pair).snapshot()\n                if any(p.enabled or p.stop_pending or p.state["active"] is not False for p in self.pairs.values()):\n                    raise ValueError("Stop puppet mode before starting a preset")').replace('(role in ("follower_left", "leader_left") and pair["mode"] != "ready")','(pair["mode"] != "ready")')
p.write_text(s)
p=Path('web/source/backend/server.py');s=p.read_text().replace('        self.presets.pair = self.pair','        self.right_pair = LeftPair(self.stop, self.publish, self.presets, side="right")\n        self.presets.pair = self.pair\n        self.presets.pairs = {"left": self.pair, "right": self.right_pair}')
s=s.replace('            if not role.endswith("_left"):\n                self.launch(self.telemetry, role, ip)\n        self.launch(self.pair.run)','        self.launch(self.pair.run)\n        self.launch(self.right_pair.run)')
s=s.replace('"puppet": self.pair.snapshot()}','"puppet": self.pair.snapshot(), "puppet_right": self.right_pair.snapshot()}')
s=s.replace('    action: Literal["arm",','    side: Literal["left", "right"] = "left"\n    action: Literal["arm",')
s=s.replace('        hub.pair.request(body.action, body.client, body.sequence)','        pair = hub.pair if body.side == "left" else hub.right_pair\n        pair.request(body.action, body.client, body.sequence)').replace('    return hub.pair.snapshot()','    return pair.snapshot()')
p.write_text(s)
p=Path('web/source/frontend/src/Controls.svelte');s=p.read_text().replace('let { state: pairState, presets, arms } = $props();','let { state: leftState, rightState, presets, arms } = $props();\n  let side = $state("left");\n  let pairState = $derived(side === "left" ? leftState : rightState);')
s=s.replace('JSON.stringify({ action, role, client, sequence: ++sequence })','JSON.stringify({ action, role, ...(kind === "puppet" ? {side} : {}), client, sequence: ++sequence })').replace("JSON.stringify({ action: 'stop', client, sequence: ++sequence })","JSON.stringify({ action: 'stop', ...(kind === 'puppet' ? {side} : {}), client, sequence: ++sequence })")
s=s.replace("'Left puppet pair'",'`${side} puppet pair`').replace('<strong>Move the left arm by hand.</strong><small>Leader left .3 → follower left .5. Absolute angles and gripper opening. Use Up on both left arms first; base headings must match.</small>','<strong>Move the {side} arm by hand.</strong><small>Leader {side} .{side === "left" ? "3" : "2"} → follower {side} .{side === "left" ? "5" : "4"}. Absolute angles and gripper opening. Use Up on both {side} arms first; base headings must match.</small>')
s=s.replace('<section class="puppet-section" aria-label="Puppet mode">','<section class="puppet-section" aria-label="Puppet mode">\n    <label>Arm pair <select aria-label="Puppet arm pair" bind:value={side} disabled={occupied}><option value="left">Left</option><option value="right">Right</option></select></label>')
s=s.replace('arms?.follower_left?.limits','arms?.[`follower_${side}`]?.limits').replace('arms.follower_left.joints[index]','arms[`follower_${side}`].joints[index]')
p.write_text(s)
p=Path('web/source/frontend/src/App.svelte');s=p.read_text().replace('operator-held left-pair controls','operator-held left / right controls').replace('<Controls state={status?.puppet}', '<Controls state={status?.puppet} rightState={status?.puppet_right}')
p.write_text(s)
print('Right paired owner, routing and side selector implemented.')
